/**
 * @file Stylelint configuration for the built token stylesheets.
 *
 * `dist/*.css` is generated by `build.mjs` from `src/tokens/*.ts`, so this checks the builder's
 * output rather than hand-written CSS. Recommended is the correctness-only set; oxfmt formats the
 * same files via `build:format`, so the stylistic rules in `-standard` would only disagree with it.
 *
 * @type {import("stylelint").Config}
 */

import { fileURLToPath } from "node:url";

/**
 * Stylelint resolves `extends` from its own location in the store rather than from this file, which
 * the isolated linker turns into "Could not find stylelint-config-recommended". Resolving it here
 * pins it to this package's own dependency.
 *
 * `import.meta.resolve` rather than `require.resolve`: the preset ships an import-only `exports`
 * map, so the CJS resolver cannot see it at all.
 */
const recommended = fileURLToPath(import.meta.resolve("stylelint-config-recommended"));
export default {
    extends: [recommended],
    rules: {
        // The generated custom properties are `--ak-<category>-<name>`, which the default pattern
        // already accepts; stated here so a builder change that breaks the shape is caught.
        "custom-property-pattern": [
            "^([a-z][a-z0-9]*)((__|--?)[A-Za-z0-9]+)*$",
            { message: "Expected generated custom property to be kebab-case" },
        ],
    },
};
